agent_clue_results = ()
for d in context:
    r = llm_query("You will analyze one document to detect a specific therapeutic agent and, if present, an FDA approval letter. Use only the document provided. Do not assume facts not in the document.\n\nDocument:\n<<<\n" + d + "\n>>>\n\nTask:\nIdentify whether this document provides any of the following clues about a single agent (drug):\n- Not indicated for patients who weigh 30 kg or are 10 years old\n- Oral administration (tablets available)\n- Reported side effect includes nausea\n- A 2022 study (published in December), authored by two people and listing 31 references, stating the half-life is less than 10 hours and the liver primarily eliminates it\n- An FDA (or regulatory) letter for tablets containing the agent where the application was received on March 23 and approval was given eight months later by letter\n\nIf the document includes any of these clues, extract them and identify the agent if possible. If the document is an FDA approval/response letter, extract the Regulatory Project Manager's full name exactly as it appears for the 'If you have any questions' contact line.\n\nOutput in this exact template (omit sections that you cannot support from THIS document):\nAgent: <exact agent name if determinable from this doc, else Unknown>\nCluesMatched: <comma-separated short list of the bulleted clues that this doc supports>\nQuotes:\n- <exact quote 1 from this doc>\n- <exact quote 2 from this doc>\n...\nIf FDA letter detected:\nRPMName: <exact full name from the letter’s 'If you have any questions' line>\nApprovalTimeline: <verbatim dates/phrases from this doc about application receipt and approval timing>\n")
    agent_clue_results = agent_clue_results + (r,)

agent_determination = llm_query("You will be given extracted clues from multiple documents. Determine the single most likely agent (drug) that satisfies ALL of the following when taken together:\n- Not indicated for patients who weigh 30 kg or are 10 years old\n- Oral route; tablets are available\n- Reported side effect includes nausea\n- A 2022 study (December), authored by two people with 31 references, reports half-life < 10 hours and primary hepatic elimination\n- There exists an FDA approval letter for tablets containing the agent: application received on March 23 and approved eight months later by letter\n\nClue Extractions:\n====\n" + "\n----\n".join(agent_clue_results) + "\n====\n\nRespond with only the exact agent name (single line). If uncertain, respond with: Unknown")

agent_name = agent_determination.strip()

letter_search_results = ()
for d in context:
    r2 = llm_query("We are looking for an FDA (or regulatory) approval/response letter for TABLETS containing the agent named exactly: " + agent_name + ". The correct letter includes:\n- A line stating the application was received on March 23\n- Approval occurred eight months later (e.g., in November of that same year)\n- A contact line: 'If you have any questions, call ... Regulatory Project Manager'\n\nUsing ONLY the document below, determine if it is that letter. If yes, extract and return:\n- The Regulatory Project Manager’s full name exactly as written (include middle initials; exclude degrees, titles, phone, and email)\n- Verbatim quotes of the application receipt date and approval timing that justify the match\n\nDocument:\n<<<\n" + d + "\n>>>\n\nOutput strictly in this template:\nIsCorrectLetter: <Yes/No>\nRPMName: <full name or None>\nEvidence:\n- <quote about March 23 receipt>\n- <quote about approval 8 months later>\n")
    letter_search_results = letter_search_results + (r2,)

final_name = llm_query("From the following analyses, pick the most plausible Regulatory Project Manager (RPM) name associated with the FDA letter for tablets containing agent '" + agent_name + "', where the application was received on March 23 and approval occurred eight months later by letter. Prefer entries with explicit matching quotes for both date conditions. If multiple candidates exist, choose the one with the strongest explicit evidence. Return only the exact full name as it appears in the letter (no titles, degrees, phone, or extra text). If nothing is sufficient, respond with: Unknown\n\nAnalyses:\n====\n" + "\n----\n".join(letter_search_results) + "\n====\n")

return_result(final_name.strip())